/* AGPL-3.0-or-later. Runs model inference away from the camera UI. */
importScripts('vendor/ort.wasm.min.js');
let session,loading,queue=Promise.resolve();
const CACHE_PREFIX='mosquito-model-';
async function sha256(bytes){if(!self.crypto?.subtle)return null;const h=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(h),b=>b.toString(16).padStart(2,'0')).join('')}
/* Cache Storage keyed by model hash: survives HTTP cache eviction, and a new model version gets a fresh cache. */
async function openCache(meta){if(!self.caches||!meta.sha256)return null;try{const name=CACHE_PREFIX+meta.sha256.slice(0,16),cache=await caches.open(name);for(const k of await caches.keys())if(k.startsWith(CACHE_PREFIX)&&k!==name)caches.delete(k).catch(()=>{});return cache}catch{return null}}
async function init(){if(session)return;if(loading)return loading;loading=(async()=>{ort.env.wasm.numThreads=1;ort.env.wasm.wasmPaths=new URL('vendor/',self.location.href).href;const r=await fetch('model/manifest.json',{cache:'no-cache'});if(!r.ok)throw Error('모델 정보를 읽을 수 없습니다');const meta=await r.json(),bytes=new Uint8Array(meta.size),cache=await openCache(meta),fresh=[];let offset=0;for(let i=0;i<meta.parts.length;i++){const url=new URL('model/'+meta.parts[i],self.location.href).href;let hit=null;if(cache)try{hit=await cache.match(url)}catch{}postMessage({progress:hit?`저장된 모기 AI 불러오기 ${i+1}/${meta.parts.length}`:`모기 AI 다운로드 ${i+1}/${meta.parts.length} · 처음 약 60 MB`});const res=hit||await fetch(url);if(!res.ok)throw Error('모델 다운로드 실패');const a=new Uint8Array(await res.arrayBuffer());if(offset+a.length>meta.size)throw Error('모델 크기 불일치');bytes.set(a,offset);if(!hit)fresh.push([url,offset,a.length]);offset+=a.length}if(offset!==meta.size)throw Error('모델 크기 불일치');postMessage({progress:'모기 AI 파일 검증 중'});const hash=await sha256(bytes);if(hash&&meta.sha256&&hash!==meta.sha256){if(cache)await caches.delete(CACHE_PREFIX+meta.sha256.slice(0,16)).catch(()=>{});throw Error('모델 파일이 손상되었습니다. 새로고침 후 다시 시도하세요')}if(cache&&hash)for(const [url,start,length] of fresh)cache.put(url,new Response(bytes.slice(start,start+length))).catch(()=>{});postMessage({progress:'모기 AI 준비 중'});session=await ort.InferenceSession.create(bytes,{executionProviders:['wasm'],graphOptimizationLevel:'all'})})().catch(e=>{loading=null;throw e});return loading}
onmessage=e=>{const msg=e.data;queue=queue.then(async()=>{try{await init();if(msg.type==='init'){postMessage({id:msg.id,ok:true});return}const input=new ort.Tensor('float32',msg.input,[1,3,640,640]);let result;try{result=await session.run({[session.inputNames[0]]:input});const out=result[session.outputNames[0]];if(out.dims.length!==3||out.dims[1]!==5)throw Error('모델 출력 형식 불일치');const data=new Float32Array(out.data);postMessage({id:msg.id,data,count:out.dims[2]},[data.buffer])}finally{input.dispose?.();if(result)Object.values(result).forEach(t=>t.dispose?.())}}catch(e){postMessage({id:msg.id,error:e.message||String(e)})}})};
